MERGE Org.Salary T
USING (SELECT * FROM @SalaryStaging) S ON T.SalaryID = S.SalaryID
WHEN MATCHED AND (
    T.BaseSalary <> S.BaseSalary OR
    T.Bonus <> S.Bonus OR
    T.Deductions <> S.Deductions
) THEN
    UPDATE SET
        BaseSalary = S.BaseSalary,
        Bonus = S.Bonus,
        Deductions = S.Deductions
WHEN NOT MATCHED THEN
    INSERT(SalaryID, BaseSalary, Bonus, Deductions, EffectiveFrom, EffectiveTo)
    VALUES(S.SalaryID, S.BaseSalary, S.Bonus, S.Deductions, S.EffectiveFrom, S.EffectiveTo);
